// Fixes known bugs in DevLink's generated helpers. The webflow/ folder is
// regenerated by the daily DevLink export, so this runs on every install/build.
import { existsSync, readFileSync, writeFileSync } from "node:fs";

const fixes = [
  // Invalid CSS easing makes the mobile navbar menu crash when opened.
  { file: "webflow/webflow_modules/utils.ts", from: '"ease--out"', to: '"ease-out"' },
];

for (const { file, from, to } of fixes) {
  if (!existsSync(file)) continue;
  const src = readFileSync(file, "utf8");
  if (src.includes(from)) {
    writeFileSync(file, src.split(from).join(to));
    console.log(`patch-devlink: fixed ${from} in ${file}`);
  }
}
